import{_ as e,o as r,c as a,a6 as d}from"./chunks/framework.De615z8S.js";const l=JSON.parse('{"title":"参考图与文件角色","description":"","frontmatter":{"id":"references","title":"参考图与文件角色","chapter":"01","status":"已公开","evidence_status":"方法已整理，未执行图像任务","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":[],"order":11},"headers":[],"relativePath":"start/references.md","filePath":"start/references.md"}'),s={name:"start/references.md"};function o(n,t,i,c,_,p){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="参考图与文件角色" tabindex="-1">参考图与文件角色 <a class="header-anchor" href="#参考图与文件角色" aria-label="Permalink to &quot;参考图与文件角色&quot;">​</a></h1><p>多图输入之前，先做素材清单。图1是真实对象，图2只参考布局，图3只参考色彩，这样比“照着做”更容易定位错误。</p><table tabindex="0"><thead><tr><th>输入</th><th>可借用的内容</th><th>需要保护的内容</th></tr></thead><tbody><tr><td>商品实拍</td><td>可见外观与包装</td><td>形状、部件、颜色、准确标识</td></tr><tr><td>竞品或风格图</td><td>场景、光线、留白关系</td><td>不挪用其商品、Logo、参数</td></tr><tr><td>人物参考</td><td>已获授权的可见特征</td><td>不凭空补未提供身份与经历</td></tr><tr><td>文案与表格</td><td>已确认文字与数值</td><td>不生成额外功效、比例或因果</td></tr></tbody></table><p>修改时另列“可改区域”和“保护区域”。提示词中的“其余不变”不能证明像素真的未变；需要精确保留时使用蒙版与图层，把原主体留在独立层，再检查修改边界。</p><p>如果照片看不清背面、接口或小字，先补素材。推测的结构可以作为概念草图，不能作为商品实物图。局部编辑见<a href="/ai-visual-creation-handbook/prompts/P06">P06</a>。</p>',5)])])}const f=e(s,[["render",o]]);export{l as __pageData,f as default};
